package main

import (
	"encoding/json"
	"fmt"
	"os"

	"github.com/segmentio/avro/go/types"
)

// Define your struct here.
type MyStruct struct {
	Name   string `json:"name"`
 Age    int     `json:"age"`
 Address string `json:"address"`
}

func main() {
	if len(os.Args) != 3 {
		fmt.Println("Usage: go run script.go <source_file> <struct_name>")
		os.Exit(1)
	}

	sourceFile := os.Args[1]
	structName := os.Args[2]

	// Parse the source file
	file, err := os.Open(sourceFile)
	if err != nil {
		fmt.Printf("Error opening file: %v\n", err)
		return
	}
	defer file.Close()

	var myStruct MyStruct
	err = json.NewDecoder(file).Decode(&myStruct)
	if err != nil {
		fmt.Printf("Error decoding JSON: %v\n", err)
		return
	}

	// Generate Avro schema
	schema, err := types.MarshalAvro(myStruct, "MySchema")
	if err != nil {
		fmt.Printf("Error generating Avro schema: %v\n", err)
		return
	}

	// Write the schema to a file
	outputFile := fmt.Sprintf("%s.avsc", structName)
	err = os.WriteFile(outputFile, []byte(schema), 0644)
	if err != nil {
		fmt.Printf("Error writing to file: %v\n", err)
		return
	}

	fmt.Printf("Generated Avro schema saved to %s.avsc\n", structName)
}
